".canvas-container canvas {
  width: 100%;
  height: 100%;
  display: block;
}

/* ----------------------------------------------------
   2.5 独立的视差背景与动态元素层 (.parallax-bg-layer)
   ---------------------------------------------------- */
.parallax-bg-layer {
  position: fixed;
  top: -5%;
  left: -5%;
  width: 110%;
  height: 110%;
  z-index: -2; /* 位于最底层 */
  will-change: transform;
  transition: transform 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  pointer-events: none;
  overflow: hidden;
}

.bg-base-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('bg_mobile_clean.webp');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.magic-clock {
  position: absolute;
  width: 25.5%;
  pointer-events: none;
  transform-origin: center;
  will-change: transform;
  filter: drop-shadow(0 0 5px rgba(229, 198, 143, 0.15));
}

.clock-tl { left: 17.2%; top: 11.0%; }
.clock-tr { left: 82.0%; top: 11.0%; }
.clock-bl { left: 17.2%; top: 89.5%; }
.clock-br { left: 82.5%; top: 89.6%; }

.clock-tl, .clock-br {
  animation: spin-cw 90s infinite linear;
}
.clock-tr, .clock-bl {
  animation: spin-ccw 110s infinite linear;
}

.magic-scales {
  position: absolute;
  width: 34.0%;
  left: 51.6%;
  top: 58.0%;
  pointer-events: none;
  transform-origin: 50% 12%; /* 旋转轴点位于天秤顶部挂环处 */
  will-change: transform;
  filter: drop-shadow(0 0 8px rgba(229, 198, 143, 0.2));
  animation: scales-swing 12s infinite ease-in-out;
}

